"""
Builds the positive definite coefficient matrix A1 (32x32) from A0 (the previous step's output) and the fixed perturbation matrix M1, by symmetrizing a linear combination and shifting by just enough of the identity to guarantee positive definiteness.

Builds a positive definite coefficient matrix $A_1$ from $A_0$ (the previous step's output) and a fixed perturbation matrix $M_1$, by symmetrizing a combination and then adding just enough of the identity to guarantee positive definiteness.










Formulas:










$X = \operatorname{symmetrize}(A_0 + 2I + 0.1M_1)$, where $\operatorname{symmetrize}(Y) = (Y + Y^{T})/2$










$A_1 = X + (|\min(0, \lambda_{\min}(X))| + 0.5)I$

Returns
-------
np.ndarray of shape (32,32), the symmetric positive definite matrix A1
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

import numpy as np


def build_matrix_A1(A0: np.ndarray, M1: np.ndarray) -> np.ndarray:
    """Build the positive definite matrix A1 from A0 and M1.

    Parameters
    ----------
    A0 : np.ndarray
        (32, 32) real symmetric matrix.
    M1 : np.ndarray
        (32, 32) real matrix.

    Returns
    -------
    A1 : np.ndarray
        (32, 32) real symmetric positive definite matrix.

    Raises
    ------
    ValueError
        If A0 or M1 does not have shape (32, 32).
    """
    A1 = np.eye(32)  # placeholder
    return A1

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np


def _oracle_build_matrix_A1(A0: np.ndarray, M1: np.ndarray) -> np.ndarray:
    A0 = np.asarray(A0, dtype=float)
    M1 = np.asarray(M1, dtype=float)
    if A0.shape != (32, 32) or M1.shape != (32, 32):
        raise ValueError("A0 and M1 must have shape (32,32)")
    n = 32
    X = A0 + 2.0 * np.eye(n) + 0.1 * M1
    X = 0.5 * (X + X.T)
    min_eig = np.linalg.eigvalsh(X).min()
    A1 = X + (abs(min(0.0, min_eig)) + 0.5) * np.eye(n)
    return A1

